/** A function whose body a violation check can walk: the checked reporter parameter sits at `reporterIndex`. */
interface CheckedFunction {
  readonly node: ts.ArrowFunction | ts.FunctionExpression | ts.FunctionDeclaration
  readonly reporterIndex: number
}

function checkInstaller(
  owner: PackageInvariantOwner,
  sourceFile: ts.SourceFile,
  sourceText: string,
  violations: PackageInvariantViolation[],
): void {
  let initializer: ts.Expression | undefined
  let declarationStatement: ts.VariableStatement | undefined
  for (const statement of sourceFile.statements) {
    if (!ts.isVariableStatement(statement)) continue
    for (const declaration of statement.declarationList.declarations) {
      if (ts.isIdentifier(declaration.name)
        && declaration.name.text === 'install'
        && declaration.initializer !== undefined) {
        initializer = declaration.initializer
        declarationStatement = statement
      }
    }
  }
  const checked = initializer === undefined ? undefined : resolveCheckedFunction(initializer, sourceFile)
  if (checked === undefined) {
    addViolation(violations, owner.sourcePath, 'must declare a local install function for package-owned checks')
    return
  }
  const { node: installer, reporterIndex } = checked
  const body = installer.body
  if (body === undefined) {
    addViolation(violations, owner.sourcePath, 'must declare a local install function for package-owned checks')
    return
  }
  if (ts.isBlock(body) && body.statements.length === 0) {
    const declarationText = declarationStatement === undefined
      ? ''
      : sourceText.slice(declarationStatement.getFullStart(), declarationStatement.getEnd())
    if (!declarationText.includes(NO_RUNTIME_INVARIANT_MARKER)) {
      addViolation(
        violations,
        owner.sourcePath,
        `empty install function must explain why with a "${NO_RUNTIME_INVARIANT_MARKER}" comment`,
      )
    }
    return
  }
  const reporter = installer.parameters[reporterIndex]?.name
  if (reporter === undefined || !ts.isIdentifier(reporter)) {
    addViolation(violations, owner.sourcePath, 'install function must accept the bound failure reporter as its second parameter')
    return
  }
  if (!usesIdentifier(body, reporter.text)) {
    addViolation(violations, owner.sourcePath, 'install function must use its bound failure reporter')
  }
}

function usesIdentifier(node: ts.Node, name: string): boolean {
  return ts.isIdentifier(node) && node.text === name
    || node.getChildren().some(child => usesIdentifier(child, name))
}

/**
 * Resolve `install`'s initializer to the function whose body the remaining
 * checks walk, and the position of the failure-reporter parameter on it.
 * Recognizes a direct installer `(ctx, fail) => ...`, the same wrapped in
 * `Object.assign(fn, { inject })`, and a call to `sessionEventValidator`
 * imported from `@deepseek-ai/dsh-invariants` — whose first argument is the
 * per-event `(prior, event, fail) => ...` check, given either inline or by a
 * local named-function reference.
 */
function resolveCheckedFunction(initializer: ts.Expression, sourceFile: ts.SourceFile): CheckedFunction | undefined {
  if (ts.isArrowFunction(initializer) || ts.isFunctionExpression(initializer)) {
    return { node: initializer, reporterIndex: 1 }
  }
  if (!ts.isCallExpression(initializer)) return undefined
  if (isObjectAssign(initializer.expression)) {
    const target = initializer.arguments[0]
