 * checks walk, and the position of the failure-reporter parameter on it.
 * Recognizes a direct installer `(ctx, fail) => ...`, the same wrapped in
 * `Object.assign(fn, { inject })`, and a call to `sessionEventValidator`
 * imported from `@deepseek-ai/dsh-invariants` — whose first argument is the
 * per-event `(prior, event, fail) => ...` check, given either inline or by a
 * local named-function reference.
 */
function resolveCheckedFunction(initializer: ts.Expression, sourceFile: ts.SourceFile): CheckedFunction | undefined {
  if (ts.isArrowFunction(initializer) || ts.isFunctionExpression(initializer)) {
    return { node: initializer, reporterIndex: 1 }
  }
  if (!ts.isCallExpression(initializer)) return undefined
  if (isObjectAssign(initializer.expression)) {
    const target = initializer.arguments[0]
    if (target === undefined || !(ts.isArrowFunction(target) || ts.isFunctionExpression(target))) return undefined
    return { node: target, reporterIndex: 1 }
  }
  if (ts.isIdentifier(initializer.expression)
    && initializer.expression.text === 'sessionEventValidator'
    && importsSessionEventValidator(sourceFile)) {
    const validateArg = initializer.arguments[0]
    const node = validateArg === undefined ? undefined : resolveNamedFunction(validateArg, sourceFile)
    return node === undefined ? undefined : { node, reporterIndex: 2 }
  }
  return undefined
}

